pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 fundAmount) public {
        vm.assume(caller != address(0) && caller != address(0x0000000000000000000000000000000000000001));
        vm.deal(address(c), fundAmount);
        vm.prank(address(this)); // set owner to test contract
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        // This call will revert because caller is not owner; we need to call as owner
        // Actually we need to call as owner to test the behavior
        // Re-design: we call as the owner, but we need to simulate a non-owner caller
        // Instead, we call as owner to trigger the function, then check balance transferred to caller
        vm.prank(address(this)); // this is the owner
        c.sudicideAnyone();
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        // Ensure sender is the owner (since constructor sets owner as msg.sender)
        // We can make the owner by using the constructor, but here we prank as the deployer
        // Actually, owner is set in constructor as msg.sender, so we need to call as that address
        // Since we deployed from this test contract, msg.sender in constructor is address(this)
        // So we prank as address(this) to call sudicideAnyone
        vm.prank(address(this));
        c.sudicideAnyone();
        // After selfdestruct, contract balance should be 0 and sent to msg.sender (address(this))
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount) public {
        // Only allow the owner to call sudicideAnyone()
        vm.assume(caller != address(0));

        // Fund the contract with some amount
        vm.deal(address(c), amount);

        // Record the owner's balance before the call
        address owner = address(this); // In test context, the test contract is the owner
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Call sudicideAnyone() as the owner
        vm.prank(owner);
        c.sudicideAnyone();

        // The contract should be destroyed; its balance should be sent to the owner
        uint256 ownerBalanceAfter = owner.balance;

        // The owner should have received the contract's balance
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore);
    }
}

